public class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> failures = new Map<Id, String>();

        List<Contact> contacts = [SELECT Id, Phone FROM Contact WHERE Id IN :contactIds];

        List<Contact> toUpdate = new List<Contact>();

        for (Contact c : contacts) {
            if (String.isBlank(c.Phone)) {
                continue;
            }
            // Strip every character that is neither a digit nor a leading '+'
            c.Phone = c.Phone.replaceAll('[^\\d+]', '');
            toUpdate.add(c);
        }

        if (!toUpdate.isEmpty()) {
            // allOrNone = false so one bad record doesn't block the rest
            List<Database.SaveResult> results = Database.update(toUpdate, false);

            for (Database.SaveResult r : results) {
                if (!r.isSuccess()) {
                    failures.put(r.getId(), r.getErrors().get(0).getMessage());
                }
            }
        }

        return failures;
    }
}
```

