            if (c.AccountId != null) {
                Account acc = accountMap.get(c.AccountId);
                if (acc != null && acc.Rating == 'Hot') {
                    c.Priority = 'High';
                }
            }
            // Every other case keeps its existing Priority.
        }
    }
