    public static void recalculate(Set<Id> accountIds) {
        // --- One bulk SOQL: fetch every open opp for the requested accounts ---
        List<Opportunity> openOpps = [
            SELECT Id,
                   AccountId,
                   StageName,
                   Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND StageName NOT IN :CLOSED_STAGES
        ];

