/**
 * Asynchronous service that keeps Account.Rating in sync with the
 * open-pipeline on an account's opportunities.
 *
 *   Hot   – at least one open opportunity with Amount >= 100 000
 *   Warm  – has open opportunities, but none that large
 *   Cold  – no open opportunities
 *
 * The @future method is designed to receive a List<Id> of accounts so
 * a single call can cover an entire CPQ batch (up to 200) without
 * hitting the 50-future-call governor limit.
 */
public class AccountRatingService {

    private static final DECIMAL HOT_THRESHOLD = 100000;

    /**
     * @param accountIds  Unique AccountIds whose Rating should be
     *                    recalculated.  Must not be null or empty.
     */
    @future
    public static void recalculate(List<Id> accountIds) {
        // ---- 1. Gather open opportunities (one bulk SOQL) ------------
        List<Opportunity> openOpps = [
            SELECT Id, AccountId, Amount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = FALSE
        ];

        // ---- 2. Group by account -------------------------------------
        Map<Id, List<Opportunity>> oppsByAccount = new Map<Id, List<Opportunity>>();
        for (Opportunity opp : openOpps) {
            oppsByAccount.computeIfAbsent(opp.AccountId, a => new List<Opportunity>).add(opp);
        }

        // ---- 3. Determine the Rating per account ---------------------
        List<Account> accountsToUpdate = new List<Account>();

        for (Id accountId : accountIds) {
            List<Opportunity> accountOpps = oppsByAccount.get(accountId);

            String rating;
            if (accountOpps == null || accountOpps.isEmpty()) {
                rating = 'Cold';
            } else {
                Boolean hasLargeOpp = false;
                for (Opportunity opp : accountOpps) {
                    if (opp.Amount != null && opp.Amount >= HOT_THRESHOLD) {
                        hasLargeOpp = true;
                        break;
                    }
                }
                rating = hasLargeOpp ? 'Hot' : 'Warm';
            }

            accountsToUpdate.add(new Account(Id = accountId, Rating = rating));
        }

        // ---- 4. One bulk DML -----------------------------------------
        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
