/**
 * Before-insert handler for OpportunityLineItem.
 *
 * Sets the standard discount (from PricingRules) on any new line whose
 * Discount is still null. Lines that already carry a Discount – including 0 –
 * are left untouched.
 *
 * Performance note
 * ---------------
 * PricingRules.standardDiscountFor executes a SOQL query per call.
 * A CPQ batch can deliver up to 200 lines on one opportunity, many of which
 * reference the same product.  Calling the method once per *line* would
 * generate up to 200 queries and exceed the 100-SOQL governor limit.
 *
 * Instead we:
 *   1. Collect the distinct Product2Ids that actually need a discount.
 *   2. Call PricingRules.standardDiscountFor once per unique product.
 *   3. Apply the cached value to every matching line in the second loop.
 *
 * The business rules remain exclusively in PricingRules; this handler only
 * orchestrates the calls and guards against redundant queries.
 */
public without sharing class LineItemDiscountHandler {

    public static void onBeforeInsert(List<OpportunityLineItem> newOLI) {
        if (newOLI == null || newOLI.isEmpty()) {
            return;
        }

        // ---- Phase 1: gather unique Product2Ids that need a default discount
        Set<Id> productsToResolve = new Set<Id>();

        for (OpportunityLineItem oli : newOLI) {
            if (oli.Discount == null && oli.Product2Id != null) {
                productsToResolve.add(oli.Product2Id);
            }
        }

        // Nothing to do – every line already has an explicit Discount.
        if (productsToResolve.isEmpty()) {
            return;
        }

        // ---- Phase 2: resolve the standard discount once per unique product
        // Each call into PricingRules.standardDiscountFor performs one SOQL,
        // so the total query count equals the number of *distinct* products
        // (typically far fewer than 200 for a real CPQ batch).
        Map<Id, Decimal> discountByProduct = new Map<Id, Decimal>();

        for (Id productId : productsToResolve) {
            discountByProduct.put(
                productId,
                PricingRules.standardDiscountFor(productId)
            );
        }

        // ---- Phase 3: apply the standard discount to each qualifying line
        for (OpportunityLineItem oli : newOLI) {
            if (oli.Discount == null && oli.Product2Id != null) {
                oli.Discount = discountByProduct.get(oli.Product2Id);
            }
        }
    }
}
```

