/**
 * After-update handler for AccountTrigger.
 *
 * When an Account's BillingCountry changes, propagate the new value to
 * MailingCountry on the account's contacts—except contacts whose
 * MailingCountry is already set to a different country (they work abroad).
 *
 * Bulk-safe: one SOQL (scoped to the changed accounts), one DML.
 * No queries in loops.
 */
public class AccountCountrySync {

    public static void handleTrigger(List<Account> oldAccounts, List<Account> newAccounts) {

        // ── 1. Identify accounts whose BillingCountry actually changed ──
        Set<Id>   changedAccountIds = new Set<Id>();
        Map<Id, String> oldCountryByAcct = new Map<Id, String>();
        Map<Id, String> newCountryByAcct = new Map<Id, String>();

        for (Integer i = 0; i < newAccounts.size(); i++) {
            Account oldAcct = oldAccounts.get(i);
            Account newAcct = newAccounts.get(i);

            if (newAcct.BillingCountry != oldAcct.BillingCountry) {
                changedAccountIds.add(newAcct.Id);
                oldCountryByAcct.put(newAcct.Id, oldAcct.BillingCountry);
                newCountryByAcct.put(newAcct.Id, newAcct.BillingCountry);
            }
        }

        // ── 2. Early exit: nothing to do ──
        if (changedAccountIds.isEmpty()) {
            return;
        }

        // ── 3. ONE query, scoped to only the accounts that changed ──
        //     Bounded by (# changed accounts × avg contacts per account),
        //     not by the total org-wide contact count.
        List<Contact> contacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ];

        // ── 4. Filter: keep only contacts whose MailingCountry is blank
        //       or matches the account's OLD BillingCountry ──
        List<Contact> toUpdate = new List<Contact>();

        for (Contact c : contacts) {
            String oldCountry = oldCountryByAcct.get(c.AccountId);
            String newCountry = newCountryByAcct.get(c.AccountId);

            // Blank (null) or same as the old HQ country → follows the move
            if (c.MailingCountry == null || c.MailingCountry == oldCountry) {
                c.MailingCountry = newCountry;
                toUpdate.add(c);
            }
            // else: works abroad, leave alone
        }

        // ── 5. ONE DML ──
        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
```

